package com.medicinemanager.controller;
import com.medicinemanager.dto.*;import com.medicinemanager.mapper.EntityMapper;import com.medicinemanager.service.MedicationService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;import java.net.URI;
@RestController @RequestMapping("/api/medications") public class MedicationController{private final MedicationService s;private final EntityMapper m;public MedicationController(MedicationService s,EntityMapper m){this.s=s;this.m=m;}@PostMapping ResponseEntity<Responses.MedicationResponse> create(@Valid @RequestBody Requests.MedicationRequest x){var created=s.create(x);return ResponseEntity.created(URI.create("/api/medications/"+created.getId())).body(m.medication(created));}@GetMapping List<Responses.MedicationResponse> all(){return s.findAll().stream().map(m::medication).toList();}@GetMapping("/{id}") Responses.MedicationResponse one(@PathVariable UUID id){return m.medication(s.find(id));}@PutMapping("/{id}") Responses.MedicationResponse update(@PathVariable UUID id,@Valid @RequestBody Requests.MedicationRequest x){return m.medication(s.update(id,x));}@DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable UUID id){s.delete(id);return ResponseEntity.noContent().build();}}
